package dev.foxphys;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/**
 * Per-block physical properties of every vanilla block (1060 blocks, default state), from
 * assets/foxphys/block-physics.json, generated by scripts/blocks/build_block_table.py.
 *
 * hardness and blast are game values. density (kg/m^3) and fragility (0..1, 1 = shatters on impact)
 * are estimates by material: Minecraft has no density property. Mods can replace any density through
 * {@link DensityTable#register}; that always wins over this table.
 */
public final class BlockPhysics {
    private BlockPhysics() {}

    static final String RESOURCE = "/assets/foxphys/block-physics.json";

    /** One block's properties. */
    public record Entry(double density, double fragility, String material, double hardness, double blast) {}

    private static final Map<String, Entry> BLOCKS = load();

    /** Entry for a full block id (for example "minecraft:stone"), or null when unknown. */
    public static Entry get(String fullId) {
        return BLOCKS.get(fullId);
    }

    /** Number of blocks in the table. */
    public static int size() {
        return BLOCKS.size();
    }

    private static Map<String, Entry> load() {
        Map<String, Entry> table = new HashMap<>();
        try (InputStream in = BlockPhysics.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                FoxPhysMod.LOGGER.warn("FoxPhys: {} is missing; densities fall back to the older table and heuristics", RESOURCE);
                return table;
            }
            JsonObject root = JsonParser.parseString(new String(in.readAllBytes(), StandardCharsets.UTF_8)).getAsJsonObject();
            for (Map.Entry<String, com.google.gson.JsonElement> e : root.getAsJsonObject("blocks").entrySet()) {
                JsonObject b = e.getValue().getAsJsonObject();
                double density = b.get("density").getAsDouble();
                double fragility = b.get("fragility").getAsDouble();
                if (!(density > 0) || !Double.isFinite(density) || fragility < 0 || fragility > 1) {
                    FoxPhysMod.LOGGER.warn("FoxPhys: block physics entry '{}' is out of range; skipped", e.getKey());
                    continue;
                }
                table.put(e.getKey(), new Entry(density, fragility, b.get("material").getAsString(),
                        b.get("hardness").getAsDouble(), b.get("blast").getAsDouble()));
            }
        } catch (IOException | RuntimeException e) {
            FoxPhysMod.LOGGER.warn("FoxPhys: block physics table is unreadable; using the older table and heuristics", e);
            table.clear();
        }
        FoxPhysMod.LOGGER.info("FoxPhys: block physics loaded, {} blocks", table.size());
        return table;
    }
}
